CREATE OR REPLACE FUNCTION public.rpc_cancel_agreement(p_agreement_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  uid uuid := auth.uid();
  v_need_id uuid;
  v_agr public.agreements%rowtype;
  v_covered integer;
  v_need public.needs%rowtype;
  v_execution public.agreement_execution%rowtype;
  v_reason text := nullif(btrim(p_reason), '');
  v_part integer;
  v_parts integer;
  v_message_prefix text;
  v_chunk_chars constant integer := 1967;
begin
  if uid is null then raise exception 'AUTH_REQUIRED' using errcode = '28000'; end if;
  if v_reason is null or v_reason ~ '^[[:space:]]*$' then
    raise exception 'REASON_REQUIRED' using errcode = 'P0001';
  end if;
  if char_length(v_reason) > 4000 then
    raise exception 'REASON_TOO_LONG' using errcode = '22023';
  end if;

  select a.need_id into v_need_id
    from public.agreements a
   where a.id = p_agreement_id;
  if not found then raise exception 'AGREEMENT_NOT_FOUND' using errcode = 'P0002'; end if;
  if not public.fn_is_party(p_agreement_id, uid) then
    raise exception 'NOT_PARTY' using errcode = '42501';
  end if;

  select * into v_need
    from public.needs n
   where n.id = v_need_id
   for update;
  if not found then raise exception 'NEED_NOT_FOUND' using errcode = 'P0002'; end if;

  select * into v_agr from public.agreements
   where id = p_agreement_id for update;
  if not found then raise exception 'AGREEMENT_NOT_FOUND' using errcode = 'P0002'; end if;
  if v_agr.need_id is distinct from v_need.id then
    raise exception 'AGREEMENT_NEED_MISMATCH' using errcode = 'P0001';
  end if;
  if not public.fn_is_party(p_agreement_id, uid) then
    raise exception 'NOT_PARTY' using errcode = '42501';
  end if;
  if v_agr.status = 'CANCELLED' then return; end if;
  if v_agr.status = 'COMPLETED' then
    raise exception 'ALREADY_COMPLETED' using errcode = 'P0001';
  end if;

  -- The same Need -> Agreement -> Execution order as completion. The action
  -- projection permits either party while CONFIRMED and only the worker after
  -- marking done. A direct RPC cannot bypass that already-published rule.
  if v_agr.status <> 'CONFIRMED' then
    raise exception 'AGREEMENT_NOT_ACTIVE' using errcode = 'P0001';
  end if;
  select * into v_execution from public.agreement_execution
   where agreement_id = p_agreement_id for update;
  if not found then
    raise exception 'EXECUTION_NOT_FOUND' using errcode = 'P0002';
  end if;
  if v_execution.agreement_version <> v_agr.current_version then
    raise exception 'EXECUTION_VERSION_MISMATCH' using errcode = 'P0001';
  end if;
  if not (v_execution.state = 'CONFIRMED'
      or (v_execution.state = 'AWAITING_REQUESTER' and uid = v_agr.worker_account_id)) then
    raise exception 'AGREEMENT_CANCELLATION_NOT_ALLOWED' using errcode = 'P0001';
  end if;

  update public.agreements set status = 'CANCELLED' where id = p_agreement_id;
  update public.agreement_execution set state = 'CANCELLED'
   where agreement_id = p_agreement_id;
  update public.need_selections set status = 'CANCELLED'
   where id = v_agr.selection_id;
  update public.marketplace_responses
     set status = 'NOT_SELECTED', selected_at = null
   where id = v_agr.selected_response_id;
  update public.access_grants
     set status = 'REVOKED',
         revoked_at = coalesce(revoked_at, statement_timestamp())
   where agreement_id = p_agreement_id and status = 'GRANTED';
  update public.notification_deliveries d
     set state = 'EXPIRED'
    from public.user_activity_events e
   where d.event_id = e.id
     and e.entity_type = 'AGREEMENT'
     and e.entity_id = p_agreement_id
     and d.state in ('CREATED','QUEUED','FAILED_RETRYABLE');

  -- Keep the reason in its existing author-owned ordinary message domain.
  -- These rows are already covered by ownAgreementMessages export and sender
  -- closure redaction. The other party's activity payload must not retain a
  -- second plaintext copy outside that author scope.
  if not private.safety_pair_blocked(v_agr.requester_account_id,v_agr.worker_account_id)
     and not private.closure_account_restricted(v_agr.requester_account_id)
     and not private.closure_account_restricted(v_agr.worker_account_id) then
    if char_length(v_reason) <= 1973 then
      insert into public.agreement_messages(agreement_id,agreement_version,sender_account_id,body)
      values(v_agr.id,v_agr.current_version,uid,'Otkazujem Dogovor. Razlog: '||v_reason);
    else
      -- PostgreSQL character slices preserve complete Unicode code points.
      -- At most three numbered messages preserve all 4,000 accepted characters.
      -- The first canonical prefix remains readable by the existing cancellation
      -- projection; subsequent parts are read in the existing conversation.
      v_parts := (char_length(v_reason)+v_chunk_chars-1)/v_chunk_chars;
      -- One random UUID prefix orders the bounded parts in the existing
      -- (created_at,id) reader while retaining the true shared statement time.
      v_message_prefix := left(gen_random_uuid()::text,35);
      for v_part in 1..v_parts loop
        insert into public.agreement_messages(id,agreement_id,agreement_version,sender_account_id,body)
        values((v_message_prefix||v_part::text)::uuid,v_agr.id,v_agr.current_version,uid,
          case when v_part=1 then 'Otkazujem Dogovor. Razlog: '||format('[%s/%s] ',v_part,v_parts)
            else format('Razlog otkazivanja [%s/%s]: ',v_part,v_parts) end
          ||substr(v_reason,(v_part-1)*v_chunk_chars+1,v_chunk_chars));
      end loop;
    end if;
  end if;

  -- A single safe terminal event identifies who cancelled and when. Existing
  -- notification privacy guards still suppress delivery to a closing account.
  -- Persist it before the closed-search completion branch can return early.
  perform private.emit_event(
    case when uid=v_agr.requester_account_id then v_agr.worker_account_id else v_agr.requester_account_id end,
    case when uid=v_agr.requester_account_id then 'WORKER' else 'REQUESTER' end,
    'AGREEMENT_CANCELLED','AGREEMENT',v_agr.id,v_agr.current_version,
    'Saradnja je otkazana','Otvorite Dogovor da vidite trenutne informacije.',
    'agreement-cancelled:'||v_agr.id::text,'NORMAL',
    jsonb_build_object('cancelledByRole',case when uid=v_agr.requester_account_id then 'REQUESTER' else 'WORKER' end),null);

  if v_need.remaining_search_closed_at is not null then
    if private.sync_need_completion(v_need.id) then
      return;
    end if;
  end if;

  v_covered := public.fn_need_covered_slots(v_agr.need_id);

  if v_covered < v_need.required_slots
     and v_need.status in ('ACTIVE','SELECTION') then
    perform set_config('uskoci.need_lifecycle', 'CANCEL_AGREEMENT', true);
    update public.needs set status = 'SELECTION' where id = v_need.id;
    perform private.enqueue_dispatch(v_need.id, statement_timestamp());
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.rpc_close_remaining_search(p_need_id uuid, p_expected_revision integer, p_client_request_id text, p_reason text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_request_id text := btrim(coalesce(p_client_request_id,''));
  v_reason text := left(btrim(coalesce(p_reason,'')),500);
  v_request_hash text;
  v_existing private.remaining_search_close_commands%rowtype;
  v_need public.needs%rowtype;
  v_selected_slots integer := 0;
  v_remaining integer := 0;
  v_affected integer := 0;
  v_result jsonb;
begin
  if v_actor is null then raise exception 'AUTH_REQUIRED' using errcode='28000'; end if;
  if p_need_id is null or p_expected_revision is null or p_expected_revision < 1 then
    raise exception 'NEED_ID_REVISION_REQUIRED' using errcode='22023';
  end if;
  if char_length(v_request_id) not between 8 and 200 then
    raise exception 'CLIENT_REQUEST_ID_INVALID' using errcode='22023';
  end if;

  v_request_hash := encode(
    extensions.digest(
      convert_to(jsonb_build_object(
        'needId',p_need_id,
        'expectedRevision',p_expected_revision,
        'reason',v_reason
      )::text,'UTF8'),
      'sha256'
    ),
    'hex'
  );

  perform pg_advisory_xact_lock(hashtextextended(v_actor::text || E'\n' || v_request_id, 4410));

  select * into v_existing
    from private.remaining_search_close_commands c
   where c.requester_account_id = v_actor
     and c.client_request_id = v_request_id
   for update;
  if found then
    if v_existing.request_hash <> v_request_hash then
      raise exception 'IDEMPOTENCY_KEY_REUSED' using errcode='22023';
    end if;
    return v_existing.result || jsonb_build_object('idempotentReplay',true);
  end if;

  select * into v_need
    from public.needs n
   where n.id = p_need_id
   for update;
  if not found then raise exception 'NEED_NOT_FOUND' using errcode='P0002'; end if;
  if v_need.requester_account_id <> v_actor then raise exception 'NEED_NOT_OWNED' using errcode='42501'; end if;
  if v_need.revision <> p_expected_revision then raise exception 'STALE_REVIEW_REQUIRED' using errcode='PT409'; end if;

  if v_need.remaining_search_closed_at is not null then
    return jsonb_build_object(
      'needId',v_need.id,
      'revision',v_need.revision,
      'requiredSlots',v_need.required_slots,
      'remainingSearchClosed',true,
      'closedAt',v_need.remaining_search_closed_at,
      'idempotentReplay',true,
      'authoritative',true
    );
  end if;

  if not exists (select 1 from public.agreements a where a.need_id = v_need.id) then
    raise exception 'REMAINING_SEARCH_CLOSE_REQUIRES_DOGOVOR' using errcode='P0001';
  end if;

  if v_need.status not in ('PUBLISHED','SELECTION','ACTIVE') then
    raise exception 'NEED_REMAINING_SEARCH_NOT_OPEN' using errcode='P0001';
  end if;

  select coalesce(sum(s.covered_slots),0)::integer
    into v_selected_slots
    from public.need_selections s
   where s.need_id = v_need.id
     and s.status = 'SELECTED';

  v_remaining := greatest(v_need.required_slots - v_selected_slots,0);
  if v_selected_slots < 1 then
    raise exception 'REMAINING_SEARCH_CLOSE_REQUIRES_SELECTED_CAPACITY' using errcode='P0001';
  end if;
  if v_remaining < 1 then
    raise exception 'NO_REMAINING_SEARCH' using errcode='P0001';
  end if;

  perform set_config('uskoci.need_lifecycle','CLOSE_REMAINING_SEARCH',true);
  update public.needs
     set remaining_search_closed_at = statement_timestamp(),
         remaining_search_closed_by_account_id = v_actor,
         remaining_search_close_reason = nullif(v_reason,''),
         updated_at = statement_timestamp()
   where id = v_need.id;
  perform set_config('uskoci.need_lifecycle','',true);

  update public.dispatch_rounds
     set status = 'STOPPED', stop_reason = 'REMAINING_SEARCH_CLOSED'
   where need_id = v_need.id
     and status in ('PLANNED','SENT');

  update public.opportunity_deliveries
     set status = 'EXPIRED'
   where need_id = v_need.id
     and status in ('READY','SEEN');

  delete from private.dispatch_schedule where need_id = v_need.id;

  -- PKG-029a (deep read 12.9): every applicant whose application closes here is told, as rpc_cancel_need does.
  with closed as (
    update public.marketplace_responses
       set status = 'EXPIRED'
     where need_id = v_need.id
       and status in ('DRAFT','SUBMITTED','DELIVERED','VIEWED','SHORTLISTED','STALE','STALE_REVIEW_REQUIRED')
     returning worker_account_id
  )
  select count(*)::integer into v_affected
    from closed c
    cross join lateral (select private.emit_event(c.worker_account_id, 'WORKER', 'NEED_CANCELLED', 'NEED', v_need.id,
      v_need.revision, 'Potraga je zatvorena',
      'Onaj ko je objavio zadatak zatvorio je potragu. Tvoja prijava više nije aktivna.',
      'search-closed:' || v_need.id::text || ':' || v_need.revision::text || ':worker:' || c.worker_account_id::text,
      'NORMAL', jsonb_build_object('reason', 'REMAINING_SEARCH_CLOSED'), null)) e;

  perform private.audit_marketplace(
    v_actor,
    'REMAINING_SEARCH_CLOSED',
    'NEED',
    v_need.id,
    v_need.revision,
    jsonb_build_object(
      'requiredSlots',v_need.required_slots,
      'selectedSlots',v_selected_slots,
      'closedRemainingSlots',v_remaining,
      'affectedResponses',v_affected,
      'reasonProvided',v_reason<>''
    )
  );

  select * into v_need from public.needs where id = v_need.id;

  v_result := jsonb_build_object(
    'needId',v_need.id,
    'revision',v_need.revision,
    'status',v_need.status,
    'requiredSlots',v_need.required_slots,
    'selectedSlots',v_selected_slots,
    'closedRemainingSlots',v_remaining,
    'affectedResponses',v_affected,
    'remainingSearchClosed',true,
    'closedAt',v_need.remaining_search_closed_at,
    'idempotentReplay',false,
    'authoritative',true
  );

  insert into private.remaining_search_close_commands(
    requester_account_id,client_request_id,request_hash,need_id,need_revision,result
  ) values (
    v_actor,v_request_id,v_request_hash,v_need.id,v_need.revision,v_result
  );

  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.rpc_withdraw_response(p_response_id uuid, p_need_revision integer, p_response_version integer, p_client_request_id text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  u uuid := auth.uid();
  v_need_id uuid;
  n public.needs;
  r public.marketplace_responses;
  v_command private.response_withdraw_commands;
  v_request_hash text;
  v_result jsonb;
  old_status text;
begin
  if u is null then raise exception using errcode='42501', message='AUTH_REQUIRED'; end if;
  if p_client_request_id is null
     or char_length(btrim(p_client_request_id)) not between 8 and 200 then
    raise exception using errcode='22023', message='INVALID_CLIENT_REQUEST_ID';
  end if;

  v_request_hash := encode(sha256(convert_to(jsonb_build_object(
    'responseId', p_response_id,
    'needRevision', p_need_revision,
    'responseVersion', p_response_version,
    'reason', btrim(coalesce(p_reason, ''))
  )::text, 'UTF8')), 'hex');

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(u::text || ':' || p_client_request_id, 7242)
  );

  select * into v_command
    from private.response_withdraw_commands c
   where c.worker_account_id = u
     and c.client_request_id = p_client_request_id;
  if found then
    if v_command.request_hash <> v_request_hash then
      raise exception using errcode='22023', message='IDEMPOTENCY_KEY_REUSED';
    end if;
    return v_command.result || jsonb_build_object('idempotentReplay', true);
  end if;

  -- Discover the parent without locking, then take locks in canonical order:
  -- Need -> Response. Selection and submission use the same order.
  select x.need_id into v_need_id
    from public.marketplace_responses x
   where x.id = p_response_id;
  if not found then raise exception using errcode='P0002', message='RESPONSE_NOT_FOUND'; end if;

  select * into n from public.needs where id = v_need_id for update;
  if not found then raise exception using errcode='P0002', message='NEED_NOT_FOUND'; end if;

  select * into r from public.marketplace_responses x
   where x.id = p_response_id for update;
  if not found then raise exception using errcode='P0002', message='RESPONSE_NOT_FOUND'; end if;
  if r.need_id <> n.id then
    raise exception using errcode='P0001', message='RESPONSE_NEED_MISMATCH';
  end if;
  if r.worker_account_id <> u then
    raise exception using errcode='42501', message='FORBIDDEN';
  end if;
  if not exists (
    select 1 from public.app_profiles p
     where p.id = r.worker_profile_id
       and p.account_id = u
       and p.kind = 'WORKER'
  ) then
    raise exception using errcode='42501', message='PROFILE_NOT_OWNED_BY_ACCOUNT';
  end if;

  if r.status = 'WITHDRAWN' then
    return jsonb_build_object(
      'responseId', r.id,
      'needId', n.id,
      'needRevision', n.revision,
      'submittedNeedRevision', r.submitted_against_need_revision,
      'version', r.current_version,
      'status', r.status,
      'withdrawnAt', r.withdrawn_at,
      'idempotentReplay', true,
      'authoritative', true
    );
  end if;

  if r.current_version is distinct from p_response_version then
    raise exception using errcode='P0001', message='STALE_REVIEW_REQUIRED';
  end if;

  if not exists (
    select 1
      from public.marketplace_response_versions v
     where v.response_id = r.id
       and v.version = r.current_version
       and v.need_revision = r.submitted_against_need_revision
  ) then
    raise exception using errcode='P0002', message='RESPONSE_VERSION_NOT_FOUND';
  end if;

  -- C12.12: every withdrawal decision binds the latest Need revision reviewed
  -- by the Worker. A live Application must also have been submitted against it;
  -- a STALE Application deliberately retains its older immutable binding.
  if n.revision is distinct from p_need_revision
     or (r.status <> 'STALE'
         and r.submitted_against_need_revision is distinct from p_need_revision) then
    raise exception using errcode='P0001', message='STALE_REVIEW_REQUIRED';
  end if;

  if r.status = 'SELECTED'
     or exists (
       select 1 from public.agreements a
        where a.selected_response_id = r.id
          and a.status in ('CONFIRMED','SUPERSEDED','COMPLETED')
     ) then
    raise exception using errcode='P0001', message='RESPONSE_ALREADY_SELECTED';
  end if;

  if r.status not in ('DRAFT','SUBMITTED','DELIVERED','VIEWED','SHORTLISTED','STALE') then
    raise exception using errcode='22023', message='RESPONSE_NOT_WITHDRAWABLE';
  end if;

  old_status := r.status;

  update public.notification_deliveries d
     set state = 'EXPIRED'
    from public.user_activity_events e
   where d.event_id = e.id
     and e.entity_type = 'RESPONSE'
     and e.entity_id = r.id
     and d.state in ('CREATED','QUEUED','FAILED_RETRYABLE');

  update public.marketplace_responses
     set status = 'WITHDRAWN',
         withdrawn_at = statement_timestamp(),
         selected_at = null
   where id = r.id
   returning * into r;

  -- A DRAFT was never visible to the requester, so withdrawing it emits no
  -- cross-party event. Submitted history remains visible and versioned.
  if old_status <> 'DRAFT' then
    perform private.emit_event(
      n.requester_account_id,
      'REQUESTER',
      'RESPONSE_WITHDRAWN',
      'RESPONSE',
      r.id,
      r.current_version,
      'Prijava je povucena',
      'Uskocer je povukao prijavu za Vasu Potrebu.',
      'response-withdrawn:' || r.id::text || ':' || r.current_version::text,
      'NORMAL',
      jsonb_build_object('needId', n.id, 'needRevision', n.revision),
      null
    );
  end if;

  -- Withdrawal can reopen capacity. Wake dispatch only while the Need can still
  -- accept a replacement; an elapsed deadline must never schedule new work.
  if n.status in ('PUBLISHED','SELECTION')
     and (n.response_deadline is null
          or n.response_deadline > statement_timestamp())
     and public.fn_need_covered_slots(n.id) < n.required_slots then
    perform private.enqueue_dispatch(n.id, statement_timestamp());
  end if;

  perform private.audit_marketplace(
    u,
    'RESPONSE_WITHDRAWN',
    'RESPONSE',
    r.id,
    r.current_version,
    jsonb_build_object(
      'needId', n.id,
      'needRevision', n.revision,
      'submittedNeedRevision', r.submitted_against_need_revision,
      'clientRequestId', p_client_request_id,
      'reason', left(btrim(coalesce(p_reason, '')), 300)
    )
  );

  v_result := jsonb_build_object(
    'responseId', r.id,
    'needId', n.id,
    'needRevision', n.revision,
    'submittedNeedRevision', r.submitted_against_need_revision,
    'version', r.current_version,
    'status', r.status,
    'withdrawnAt', r.withdrawn_at,
    'idempotentReplay', false,
    'authoritative', true
  );

  insert into private.response_withdraw_commands (
    worker_account_id, client_request_id, request_hash,
    response_id, response_version, result
  ) values (
    u, p_client_request_id, v_request_hash,
    r.id, r.current_version, v_result
  );

  return v_result;
end;
$function$
